head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > E > onresetclick]<br/>SearchBox 컴포넌트의 Reset 버튼을 클릭했을 때 발생합니다.",
    "validation" : [
        "키보드의 Enter 키 또는 Space 키로 Reset 버튼이 클릭된 경우도 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (accessibility=true : 키보드 접근성 활성화 - Reset 버튼이 키보드 포커스 가능)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 테스트 방법 안내 라벨 생성
    $c.gcm.createLabel('label="[테스트 방법] Tab 키로 Reset 버튼에 포커스 후 Enter, Space 키 입력하여 이벤트 발생 확인"', '', 'label1');

    // target1 (accessibility=true, Reset 버튼 표시) : onresetclick 등록
    let properties = {
        accessibility : true,
    };
    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onresetclick"], 'target1');
    await $c.gcm.createBasicSearchBox(cList, eList, 'target1');
}



// target1 onresetclick 핸들러 - e 는 한 줄 출력
scwin.target1_onresetclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onresetclick 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("e:" + e);
};
